dius:6px}.receipt-grid{display:grid;grid-template-columns:1.2fr .6fr .8fr 1fr;gap:10px;align-items:end;margin:8px 0}@media(max-width:760px){.top{display:block}.actions{margin-top:14px}.meta,.receipt-grid{grid-template-columns:1fr}.receipt-record-head,.receipt-record-item{display:grid;grid-template-columns:1fr}table{display:block;overflow:auto}}
